package com.bank.tenure;

import java.time.*;
import java.util.logging.*;

public class TenureDemo {
    private static final Logger log = Logger.getLogger("Tenure");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // fixed clock → deterministic output (as if today is 2025-06-01)
        Clock clock = Clock.fixed(Instant.parse("2025-06-01T00:00:00Z"), ZoneOffset.UTC);
        TenureService service = new TenureService(clock);

        long years = service.tenureYears("2020-01-15");
        log.info(() -> "Joined 2020-01-15 → tenure = " + years + " years");
        log.info(() -> "bad date → " + service.tenureYears("not-a-date"));
    }
}

// ─── Would be in service/TenureService.java ───
class TenureService {
    private final Clock clock;
    TenureService(Clock clock) { this.clock = clock; }

    long tenureYears(String joinDateText) {
        try {
            LocalDate join = LocalDate.parse(joinDateText);          // ISO yyyy-MM-dd
            LocalDate today = LocalDate.now(clock);                  // injectable clock
            return java.time.temporal.ChronoUnit.YEARS.between(join, today); // complete years
        } catch (java.time.format.DateTimeParseException ex) {
            return -1;   // invalid input sentinel
        }
    }
}
